import sys
from math import gcd

sys.setrecursionlimit(200000)

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    n = int(next(iterator))

    x = [0] * (n + 1)
    for i in range(1, n + 1):
        x[i] = int(next(iterator))

    adj = [[] for _ in range(n + 1)]
    for _ in range(n - 1):
        u = int(next(iterator))
        v = int(next(iterator))
        adj[u].append(v)
        adj[v].append(u)

    MOD = 10**9 + 7

    visited = [False] * (n + 1)
    total_sum = 0

    def dfs(u, p):
        nonlocal total_sum

        current_map = {}
        if p == 0:
            if x[u] > 0:
                current_map[x[u]] = 1
            else:
                current_map[0] = 1
        else:
            parent_map = dfs(p, 0)

            new_map = {}
            for val, count in parent_map.items():
                g = gcd(val, x[u])
                if g not in new_map:
                    new_map[g] = 0
                new_map[g] += count

            if x[u] > 0:
                if x[u] not in new_map:
                    new_map[x[u]] = 0
                new_map[x[u]] += 1
            else:
                if 0 not in new_map:
                    new_map[0] = 0
                new_map[0] += 1

            current_map = new_map

        for val, count in current_map.items():
            term = (val % MOD) * (count % MOD)
            total_sum = (total_sum + term) % MOD

        return current_map

    dfs(1, 0)
    print(total_sum)

if __name__ == "__main__":
    main()
